    linkcolor = red,
    anchorcolor = green!50!black,
    citecolor = green!50!black,
    filecolor = green!50!black,
    urlcolor = green!50!black
}
\usepackage{cleveref}

\usepackage[top=1in, bottom=1in, left=1.25in, right=1.25in]{geometry}
